#include <curl/curl.h>
#include <stdio.h>
#include <stdlib.h>
int main(void){const char *key=getenv("HANZO_API_KEY"),*base=getenv("HANZO_BASE_URL");if(!key)return 2;if(!base)base="https://api.hanzo.ai/v1";char url[2048],auth[4096];if(snprintf(url,sizeof url,"%s/worlds",base)>=(int)sizeof url||snprintf(auth,sizeof auth,"Authorization: Bearer %s",key)>=(int)sizeof auth)return 2;CURL *c=curl_easy_init();if(!c)return 2;struct curl_slist *h=NULL;h=curl_slist_append(h,auth);h=curl_slist_append(h,"Content-Type: application/json");curl_easy_setopt(c,CURLOPT_URL,url);curl_easy_setopt(c,CURLOPT_HTTPHEADER,h);curl_easy_setopt(c,CURLOPT_POSTFIELDS,"{\"model\":\"sekai-1-alpha\",\"domain\":\"simulation\"}");curl_easy_setopt(c,CURLOPT_TIMEOUT,30L);curl_easy_setopt(c,CURLOPT_FAILONERROR,1L);CURLcode result=curl_easy_perform(c);long status=0;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&status);curl_slist_free_all(h);curl_easy_cleanup(c);return result==CURLE_OK&&status>=200&&status<300?0:1;}
